export function enhance(exps){
 const pol=exps.find(e=>e.id==='polarization');
 const range=(key,label,min,max,step,value,unit='')=>({key,label,min,max,step,value,unit});
 const select=(key,label,options,value)=>({key,label,options,value});
 pol.title='Як побачити, що під водою?';pol.sub='Поляризація світла: від відблисків до одного й кількох фільтрів';pol.short='Поверни фільтр, прибери відблиск і досліди напрям коливань світла.';
 pol.fields=[select('mode','Що досліджуємо',[['lab','Хвиля та поляризатори'],['water','Відблиск на воді']],'lab'),select('input','Світло перед фільтром',[['unpolarized','Неполяризоване: змінні напрями'],['linear','Лінійне: один напрям'],['circular','Колове: обертання по колу'],['elliptical','Еліптичне: обертання по еліпсу']],'unpolarized'),range('inputAngle','Поворот вхідної поляризації',0,180,1,0,'°'),range('ellipticity','Відношення півосей еліпса',.2,1,.05,.5),range('incidence','Кут падіння на воду від нормалі',0,85,1,53,'°'),select('count','Скільки поляризаторів',[['1','Один'],['2','Два'],['3','Три']],'1'),range('first','Вісь першого фільтра',0,180,1,0,'°'),range('middle','Вісь середнього фільтра',0,180,1,45,'°'),range('angle','Вісь останнього фільтра',0,180,1,90,'°')];
 pol.fields.push(range('camera','Поворот 3D ракурсу',15,60,1,35,'°'));
 pol.note='Помаранчеві вектори — електричне поле E, бірюзові — магнітне поле B. Обидва перпендикулярні до напряму поширення й одне до одного; у вакуумі B = E/c за модулем. Для читабельності B показано в масштабі cB, тобто довжини стрілок E та B не можна порівнювати як значення в однакових одиницях. Крива з’єднує кінчики векторів у різних точках простору, а не показує шлях фотона. Поверни 3D ракурс повзунком, щоб побачити обидві поперечні компоненти. Час сповільнений умовно. Для неполяризованого світла показано умовну реалізацію двох неузгоджених поперечних компонент; це не одна стала еліптична хвиля. Інтенсивності обчислюються як середні за статистичною моделлю, а не з одного кадру. У водному режимі вхід — відбиття неполяризованого світла від гладкої води (n = 1,333). Малюнок дна умовний: це демонстрація контрасту, не розрахунок зображення водойми.';
 pol.theory.splice(2,0,['Як читати просторову хвилю','Стрілка E показує напрям і величину електричного поля в обраній точці. Стрілка B так само показує магнітне поле. Вони спрямовані поперек поширення світла й перпендикулярні одна до одної. Разом їхні напрями визначають, куди переноситься енергія. На малюнку помаранчева й бірюзова криві з’єднують кінчики цих стрілок у різних точках простору в один момент часу. Після лінійного поляризатора E залишається вздовж його осі, а B — перпендикулярно до неї. Поворот ракурсу змінює лише вигляд, а не фізичні параметри досліду.<div class="formula">E ⟂ B; E ⟂ k; B ⟂ k<br>B = E/c; c ≈ 3 × 10<sup>8</sup> м/с</div>k тут позначає напрям поширення. E вимірюють у В/м, B — у теслах (Тл). У візуалізації довжина бірюзових стрілок відповідає cB, щоб обидва поля було видно; це окреме масштабування одиниць. Неполяризований вхід показано умовною неузгодженою сумішшю компонент, а його інтенсивність усереднюється.']);
 pol.observe='Почни з одного фільтра: поверни його й подивися на поле після нього. Порівняй види вхідної поляризації. Для двох постав осі 0° та 90°; потім додай середній під 45°. У режимі води порівняй відблиск при осі 0° і 90° поблизу 53° падіння.';
 pol.preset={mode:'lab',input:'unpolarized',count:3,first:0,middle:45,angle:90};
 pol.task='1. Один фільтр, неполяризований вхід: запиши інтенсивність при 0°, 45°, 90°. 2. Лінійний вхід: повтори й порівняй із cos²θ. 3. Два фільтри 0°/90°, потім три 0°/45°/90°: порівняй 0 та 0,125. 4. Вода, один фільтр: порівняй 0°/90° при падінні 53°. Записуй кожен стан у журнал. Графік показує обертання першого фільтра для одного фільтра або останнього для кількох.';
 pol.limit='Ідеальні лінійні поляризатори. Лінійна, колова та еліптична поляризації — повністю поляризовані стани; неполяризоване світло — статистична суміш. Для води використано коефіцієнти Френеля, плоску гладку поверхню, неполяризоване освітлення; хвилі води, розсіювання, глибина й реальні окуляри не моделюються.';
 const mol=exps.find(e=>e.id==='molecule');mol.note+=' У вкладці енергетичних рівнів коло виділяє область загальної схеми, яку показано збільшено. Один запуск показує один процес і зупиняється; крапка позначає стан молекули, не просторове положення електрона. У флуоресценції стрілка вгору означає поглинання 3,10 еВ, проміжна вниз — передачу 0,70 еВ оточенню, а остання вниз — випромінювання 2,40 еВ.';
 const atom=exps.find(e=>e.id==='atom');atom.fields.unshift(select('species','Який атом досліджуємо',[['H','Гідроген (водень) — H I'],['He','Гелій — He I'],['O','Оксиген (кисень) — O I'],['N','Нітроген (азот) — N I'],['Fe','Залізо — Fe I'],['Na','Натрій — Na I'],['Ne','Неон — Ne I']],'H'),select('atomicLine','Табличний перехід',[['yellow','Жовта лінія'],['red','Червона лінія'],['uv','Ультрафіолетова лінія'],['violet','Фіолетова лінія'],['blue','Синя лінія'],['d2','D₂'],['d1','D₁']],'yellow'));atom.sub='Дозволені енергії та переходи між ними: це не схема заповнення електронних шарів';atom.fields.find(f=>f.key==='upper').label='Вищий дозволений рівень n';atom.fields.find(f=>f.key==='lower').label='Нижчий дозволений рівень n';atom.theory=atom.theory.map(([title,body])=>['Для Гідрогену: '+title,body]);atom.theory.unshift(['Один електрон — багато можливих енергій','Нейтральний Гідроген має лише один електрон. В основному стані він займає орбіталь 1s з n = 1. Перший період таблиці відповідає заповненню першого шару в основному стані, але не забороняє збуджувати атом. Після отримання енергії електрон може опинитися на вищому дозволеному рівні n = 2, 3 і далі. Одночасного заповнення всіх рисок на схемі немає: одна крапка позначає поточний стан. У цій моделі водню дозволених збуджених енергій нескінченно багато; для зручності показано перші десять. Щоб показати випромінювання, атом на початку умовно вже підготовлений у вибраному збудженому стані. Наприклад, після 3 → 2 він ще збуджений; основного стану досягає лише при переході на n = 1. Для багатоелектронних атомів риски означають енергії всього атома, а не кількість його електронів чи зайнятих шарів. Дві риски табличного переходу — два обрані стани з набагато більшого набору.']);atom.theory.unshift(['Який саме атом ми розглядаємо','Вибір над повзунками визначає атом. Позначення H I, He I, O I та інші з римською I означають нейтральний атом: він має стільки електронів, скільки протонів у ядрі. Це не молекули H₂, O₂ чи N₂. Для Гідрогену збережено навчальну формулу рівнів −13,5983/n² еВ. Для Гелію, Оксигену, Нітрогену, Заліза, Натрію й Неону вона не застосовується: тут вибираємо пару табличних станів із довідника NIST. Показано лише кілька переходів, не повний спектр елемента. Позначення станів містять конфігурацію електронів і квантові характеристики; їх не слід читати як номер водневої орбіти. Енергія фотона для кожної пари дорівнює різниці енергій станів.<div class="formula">ΔE = E<sub>верх</sub> − E<sub>низ</sub><br>λ<sub>вак</sub> = hc/ΔE</div>У таблицях NIST енергії часто наведені в см⁻¹: помноження різниці цих значень на hc переводить її в енергію. Звідси λ у нанометрах = 10⁷ / Δ(см⁻¹). Табличні оптичні довжини хвиль зазвичай наведені для повітря, тому вони трохи коротші за λ у вакуумі. Інтерфейс підписує обидва значення. Усі анімації умовні й показують один підготовлений перехід.']);atom.note='Атом обирається у налаштуваннях. Гідроген — модель одного електрона; інші нейтральні атоми — вибрані табличні пари станів NIST. Один запуск показує один перехід. Атом залишається у кінцевому стані до повторного запуску або скидання. Риски — дозволені енергії; крапка — поточний стан атома. Для Гідрогену це стан його одного електрона. Риски не означають одночасно зайняті шари. Випромінювання починається з умовно підготовленого збудженого стану. Хвильовий пакет — умовне позначення фотона, не його форма або точна траєкторія. Для видимого світла колір обчислено за довжиною хвилі; відстань між гребенями пропорційна λ в умовному масштабі. Для УФ та ІЧ колір і форма пакета умовні. Час переходу й швидкість позначки сповільнені для демонстрації та не відтворюють час життя стану або швидкість світла.';atom.observe='Обери випромінювання та перехід 3 → 2: побачиш червоне світло близько 656 нм. Порівняй із 4 → 2: синьо-зелений фотон близько 486 нм, із коротшим кроком хвильки. Після одного переходу електрон залишається внизу. Щоб повторити, натисни «Повторити перехід» або «Скинути». У поглинанні хвилька рухається до атома й зникає під час переходу вгору.';
 const ref=exps.find(e=>e.id==='refraction');ref.fields.push(range('prismAngle','Кут падіння на призму від нормалі',25,75,1,50,'°'),range('apex','Кут між гранями призми A',45,65,1,60,'°'),select('prismView','Що розглянути',[['overview','Уся призма'],['entry','Вхід: повітря → призма'],['exit','Вихід: призма → повітря']],'overview'),range('prismZoom','Масштаб зображення',1,10,.5,1,'×'));ref.task='У режимі призми обери скло й A = 60°. Порівняй кути падіння 40°, 50°, 70°; для кожного запиши δ для 400 та 700 нм. Повтори для води. Потім зменш кут падіння до 25° і перевір, які кольори виходять через другу грань. Зістав спостереження з умовою |n sin r₂| > 1.';ref.note='Білий промінь містить усі показані довжини хвиль 400–700 нм. Кольори розходяться вже після першої грані; на другій кожен заломлюється повторно. Загальний вид зберігає геометричні кути. У видах входу й виходу різницю напрямів кольорів відносно опорного кольору (зазвичай 550 нм) збільшено у 20 разів для видимості; це не зміна фізики або показника заломлення. Повзунок масштабу збільшує зображення навколо обраної ділянки. Промені обчислено за законом заломлення на обох гранях; кути вимірюються від нормалей. Яскравість кольорів умовна. При повному внутрішньому відбитті показано перший відбитий відрізок; подальші відбиття всередині не простежуються. Втрати й відбиті частки при звичайному заломленні не моделюються.';ref.theory=ref.theory.filter(([title])=>!['Чому призма розкладає біле світло','Яка модель речовини використана'].includes(title));ref.theory.push(['Чому призма розділяє біле світло','Біле світло містить багато довжин хвиль. У прозорому матеріалі світло взаємодіє зі зв’язаними електричними зарядами; їхня відповідь залежить від частоти. Тому швидкість поширення хвилі v залежить від її довжини, а разом із нею змінюється показник заломлення n = c/v. Цю залежність називають дисперсією. У видимому діапазоні нашої моделі скла фіолетове світло має більший n, ніж червоне: при вході воно сильніше повертає до нормалі. На виході кожен колір ще раз заломлюється, тому білий промінь розділяється. Частота під час переходу не змінюється; довжина хвилі в матеріалі стає меншою.<div class="formula">n(λ₀) = c/v(λ₀)<br>λ<sub>мат</sub> = λ₀/n(λ₀)<br>n(λ₀) = a + b/λ₀<sup>2</sup></div>λ₀ — довжина хвилі у вакуумі. Остання формула — наближення Коші. Тут λ₀ підставляють у мікрометрах: 400 нм = 0,4 мкм. Для скла a = 1,5046, b = 0,0042 мкм²; для води a = 1,322, b = 0,003 мкм²; для повітря n = 1. Це навчальні наближення для видимого діапазону. Призма з водою означає ідеальну призматичну межу води без урахування стінок посудини.'],['Дві грані — два обчислення','Спочатку проведи перпендикуляр до вхідної грані — нормаль. Кут i між падаючим променем і цією лінією є кутом падіння. Усередині кут до тієї самої нормалі позначено r₁. На другій грані потрібна інша нормаль: кут до неї всередині — r₂, а після виходу — e. A — кут між гранями призми. Для кожної довжини хвилі обчислення окреме:<div class="formula">sin i = n(λ₀) sin r<sub>1</sub><br>r<sub>1</sub> = arcsin[sin i / n(λ₀)]<br>r<sub>2</sub> = A − r<sub>1</sub><br>sin e = n(λ₀) sin r<sub>2</sub><br>δ(λ₀) = i + e − A<br>Δδ = |δ(400 нм) − δ(700 нм)|</div>δ — поворот променя від початкового напряму після двох заломлень. Δδ показує кутове розділення фіолетового та червоного. Якщо |n sin r₂| > 1, дійсного кута виходу немає: світло повністю відбивається всередину. У цьому випадку не можна підставляти довільний кут або малювати вихідний спектр для цього кольору.']);ref.theory.push(['Чому кольори розходяться і всередині','На першій грані для кожної довжини хвилі виходить своє r₁: навіть усередині призми червоний та фіолетовий промені вже мають різні напрями. У звичайному склі різниця невелика, тому на загальному малюнку тонкі лінії перекриваються. Після другої грані кути виходу теж різні. Для показаних матеріалів при виході через другу грань кутове розділення зазвичай стає більшим; його розмір залежить від матеріалу, кута падіння й форми призми. Промінь у кожному однорідному матеріалі між гранями йде прямо: безперервного вигинання всередині немає. Зміна напрямку відбувається на гранях. Вибери «Вхід» або «Вихід», щоб побачити обидва етапи окремо. У цих навчальних видах різниці напрямів збільшені у 20 разів; розраховані кути під малюнком залишаються незбільшеними.']);ref.observe='Обери режим над малюнком. «Заломлення» показує один колір на межі середовищ; «Дисперсія» — біле світло в призмі. Порівняй показники заломлення й кути для 400 та 700 нм. Змінюй кут падіння, кут призми та матеріал. У режимі призми вхід завжди білий: показано всі кольори 400–700 нм одночасно. Обери збільшений вид входу або виходу та змінюй масштаб. У збільшених видах різницю напрямів кольорів додатково підсилено у 20 разів і явно підписано; числові кути залишаються фізичними. Пунктир — нормаль, тобто перпендикуляр до грані. Порівняй 400 і 700 нм; при деяких налаштуваннях на другій грані виникає повне внутрішнє відбиття.';
 atom.theory.push(...[["Чому не кожен перехід однаково ймовірний", "Атом може мати два стани з різними енергіями, але самої різниці енергій недостатньо, щоб він легко випромінив фотон. Важливо також, як у цих станах розподілені електрони та як їхній стан взаємодіє зі світлом. Найсильніший і найчастіший механізм називають електричним дипольним випромінюванням, скорочено E1. Квантова фізика задає умови, за яких він можливий, — правила відбору. Для деяких пар станів внесок саме цього механізму дорівнює нулю. Такі переходи називають забороненими для E1. Це не означає, що енергія зникає чи що перехід неможливий за будь-яких умов."], ["Чому «заборонений» усе ж відбувається", "Слабші способи взаємодії атома зі світлом можуть дати ненульову ймовірність: наприклад, магнітне дипольне (M1) або електричне квадрупольне (E2) випромінювання. Кожен із них має власні правила відбору; не будь-яка заборонена для E1 пара обов’язково допускає M1 чи E2. Для відповідних слабких переходів імовірність за одиницю часу зазвичай набагато менша, ніж для сильних дозволених. Атом або йон може довго залишатися збудженим. Такий довгоживучий стан називають метастабільним. «Мала ймовірність» тут означає повільний процес для окремого збудженого атома, а не обов’язково слабку лінію від цілої туманності. На Землі такі переходи теж спостерігають, якщо створити відповідні умови."], ["Чому їх видно в космосі", "У густому газі частинки часто зіштовхуються. Зіткнення може забрати енергію збудження до того, як атом устигне випромінити слабким механізмом: енергія перейде в рух частинок без цього фотона. Це називають зіткнювальним гасінням. У розрідженому газі туманностей зіткнення значно рідші. Збуджений атом або йон має час випромінити, навіть якщо перехід повільний. Атомів дуже багато, тому разом вони можуть утворювати яскраву спектральну лінію. Важливі також температура, кількість збуджених частинок і стан іонізації: не весь космос має однакові умови."], ["Два способи втратити енергію: проста модель", "Позначимо ймовірність випромінювального переходу за одиницю часу літерою A, у с⁻¹. Без інших каналів середній час очікування дорівнює 1/A. Це середній час, а не таймер кожного атома. Нехай n<sub>e</sub> — концентрація електронів, а q — коефіцієнт зіткнювального гасіння при обраній температурі. Якщо n<sub>e</sub> задано в м⁻³, то q має одиниці м³/с. Тоді n<sub>e</sub>q — швидкість гасіння, теж у с⁻¹.<div class=\"formula\">τ = 1/A<br>Γ<sub>зітк</sub> = n<sub>e</sub>q<br>P<sub>фотон</sub> = A / (A + n<sub>e</sub>q)<br>n<sub>крит</sub> = A/q</div>У цій спрощеній моделі є лише два конкуруючі виходи з одного збудженого стану. P<sub>фотон</sub> — імовірність випромінити до зіткнювального гасіння. При n<sub>e</sub> ≪ n<sub>крит</sub> вона близька до 1; при n<sub>e</sub> ≫ n<sub>крит</sub> мала. За критичної концентрації обидві швидкості однакові, і P<sub>фотон</sub> = 1/2. Для реальних багаторівневих атомів потрібно враховувати всі виходи та їхні швидкості. Формула E = hc/λ визначає енергію фотона, але не швидкість переходу."], ["Приклад: зелене світло туманностей", "У спектрах туманностей часто спостерігають зелену лінію [O III] поблизу 500,7 нм. Її випромінює Оксиген, який утратив два електрони, — йон O²⁺. Позначення III означає третю спектроскопічну стадію: I — нейтральний атом, II — один утрачений електрон, III — два. Квадратні дужки позначають заборонену лінію. Це інша частинка й інший перехід, ніж нейтральний O I, який можна обрати в нашій симуляції. Низька концентрація газу дає цьому збудженому йону час випромінити. Такі лінії допомагають досліджувати умови в газі. <a href=\"https://academic.oup.com/mnras/article/396/2/788/1025056\" target=\"_blank\" rel=\"noopener\">Дослідження заборонених ліній і густини туманностей ↗</a>"], ["Що показує наша схема переходів", "Рівні n у навчальній моделі Гідрогену задають енергії, але одного n недостатньо для перевірки правил відбору: усередині рівня є стани з різними квантовими характеристиками. Тому вибір двох n не означає, що будь-який перехід між усіма їхніми підстанами дозволений. Для багатоелектронних атомів потрібні повні характеристики конкретних станів. Анімація тут показує зміну енергії й фотон, а не розрахунок імовірності переходу або справжній час життя стану. Вибір нейтрального Оксигену не моделює автоматично заборонену лінію [O III]. <a href=\"https://physics.nist.gov/PhysRefData/ASD/Html/lineshelp.html\" target=\"_blank\" rel=\"noopener\">NIST: правила відбору й типи переходів ↗</a>"]]);

 const bb=exps.find(e=>e.id==='blackbody');bb.fields.push(select('starColourMode','Як показувати колір зорі',[['schematic','Схематичний колір класу'],['calculated','Розрахований колір чорного тіла']],'schematic'));bb.note='За замовчуванням диск показує умовний колір спектрального класу: M — червоний. Перемкни «Як показувати колір зорі», щоб порівняти з розрахованим sRGB-кольором чорного тіла, нормованим за яскравістю. Умовний колір класу не є точним відтворенням видимого відтінку. Видимий розмір умовний. Клас орієнтовний за температурою; реальна класифікація спирається на спектральні особливості.';bb.observe='Порівняй 2500, 5800 і 15000 К. Перемкни схематичний колір класу на розрахований колір чорного тіла. Для 5300 К максимум близько 547 нм, але розрахований диск близький до білого: одночасно випромінюються всі видимі кольори. Видима ділянка на графіку позначена смугою 380–780 нм.';bb.theory=bb.theory.filter(([title])=>title!=='Зелений максимум і біле світло');bb.theory.push(...[["Чому клас M позначаємо червоним", "Найхолодніші зорі цієї послідовності називають червоними зорями класу M. У навчальних схемах M показують червоним, K — помаранчевим, G — жовтим, а гарячіші класи — білим та блакитним. Це умовні кольори категорій, а не точна фотографія зорі. За 2500 К максимум B<sub>λ</sub> лежить приблизно на 1159 нм, у невидимому інфрачервоному діапазоні. У видимій частині спектра більше довгохвильового світла, тому зоря має теплий червонуватий відтінок. Це не означає, що вона випромінює лише червоні фотони."], ["Чому два способи показу мають різні відтінки", "У режимі «Схематичний колір класу» диск має умовний колір класу: M — червоний. У режимі «Розрахований колір чорного тіла» підсумовуємо весь видимий тепловий спектр з урахуванням наближеної чутливості людського зору й переводимо результат у sRGB для екрана. Максимальну компоненту яскравості нормуємо: холодна зоря не стає майже невидимою поруч із гарячою. За 2500 К такий нормований диск може виглядати помаранчевим. Це не помилка закону Планка й не зміна класу M на K. Реальні зоряні атмосфери мають лінії та молекулярні смуги поглинання, яких немає в ідеального чорного тіла; відтінок також залежить від яскравості, адаптації зору й налаштувань зображення. Навіть умовно «жовте» Сонце поза атмосферою виглядає близьким до білого."], ["Чому зелений максимум не дає зелену зорю", "У сітківці є три типи колбочок — світлочутливих клітин, які реагують на широкі, перекривні ділянки спектра. Мозок порівнює їхні сигнали й формує відчуття кольору. Тепловий спектр широкий: якщо його вершина потрапила в зелену ділянку, червона й синя частини теж залишаються сильними. Вони разом збуджують усі три типи колбочок, і суміш виглядає близькою до білої. Для насиченого зеленого відтінку потрібно, щоб середня частина видимого спектра переважала значно сильніше, ніж у гладкій кривій Планка. Самої наявності зелених фотонів або максимуму біля 550 нм недостатньо. Звичайні фотосфери зір не утворюють насичено зеленого теплового кольору. Зелені лінії газової туманності мають інший, вузьколінійний спектр; видимі зеленуваті відтінки на зображеннях можуть також виникати через обробку чи колірний контраст."], ["Перевір максимум у зеленому самостійно", "Встанови T = 5300 К і вибери розрахований колір чорного тіла. Закон Віна дає λ<sub>max</sub> ≈ 547 нм — зелену область, але диск не зелений. На графіку виділена вся видима ділянка 380–780 нм: крива не обривається з обох боків максимуму.<div class=\"formula\">λ<sub>max</sub> = b/T ≈ 547 нм<br>B<sub>λ</sub>(450 нм) / B<sub>λ</sub>(λ<sub>max</sub>) ≈ 0,91<br>B<sub>λ</sub>(650 нм) / B<sub>λ</sub>(λ<sub>max</sub>) ≈ 0,93</div>Це значення спектральної яскравості на одиницю довжини хвилі, а не частки всієї енергії чи сигнали колбочок. Приклад показує: синє та червоне світло майже не поступаються вершині. Потім порівняй 2500, 5800 і 15000 К. Радіус змінює світність, але за сталої температури не змінює колір у цій моделі. <a href=\"https://lco.global/spacebook/light/black-body-radiation/\" target=\"_blank\" rel=\"noopener\">Las Cumbres Observatory: тепловий спектр і колір зір ↗</a>"]]);

 const wave=exps.find(e=>e.id==='wave');wave.axis=['Координата x, мкм','E / E₀,ref'];wave.fields.find(f=>f.key==='amp').label='Відносна амплітуда E<sub>0</sub> / E<sub>0,ref</sub>';wave.note+=' Просторова ділянка має сталу довжину 1,65 мкм: зміна λ змінює відстань між гребенями. Шкала поля на графіку стала, тому зміна амплітуди видима. Рух умовно сповільнений однаково для всіх λ: коротші хвилі коливаються швидше.';
 const dif=exps.find(e=>e.id==='diffraction');dif.theory.push(['Який мінімум показує ґратка','У багатощілинній картині є вузькі смуги від усіх N щілин та ширша огинаюча однієї щілини. Найближчий до центру мінімум усієї ґратки лежить при γ = π/N, тому:<div class="formula">sin θ₁ = λ/(Nd)<br>sin θ<sub>огин</sub> = λ/a</div>Другий кут задає перший мінімум огинаючої. Вони різні, і результати показують обидва. Головний максимум ґратки може зникнути, якщо збігається з нулем огинаючої. Кільце Ейрі для круглого отвору використовує діаметр D, а не період ґратки.']);
 const sky=exps.find(e=>e.id==='sky');sky.observe+=' Вибір CO₂ не задає атмосферу Марса: пилове розсіювання тут відсутнє.';sky.limit+=' Режим Марса — окрема пояснювальна ілюстрація, не кількісна модель пилу.';sky.sub='Розсіювання молекулами та чому на Марсі все інакше';sky.short='Порівняй газову модель із поясненням рудого неба й блакитного заходу на Марсі.';sky.fields.unshift(select('mode','Режим неба',[['gas','Розрахунок: газова атмосфера'],['mars','Марс: пояснювальна схема']],'gas'),select('marsTime','Марс: час доби',[['day','День'],['sunset','Захід Сонця']],'day'));sky.fields.find(f=>f.key==='gas').options=[['air','Умовне повітря: ×1'],['co2','Умовний CO₂: ×2,5 — не модель Марса'],['hydrogen','Умовний H₂: ×0,2']];sky.preset.mode='gas';sky.preset.marsTime='day';sky.theory.unshift(['Чому на Марсі небо інше','На Землі в чистому повітрі важливе розсіювання на молекулах. На Марсі тонка атмосфера містить завислий мінеральний пил: його частинки значно більші за молекули, тож залежність λ⁻⁴ для них загалом не працює. Денне марсіанське небо часто має жовтуватий, рудий або коричнюватий відтінок. Біля заходу блакитне сяйво помітне переважно навколо Сонця; решта неба може залишатися жовто-помаранчевою. Це пов’язано з тим, як пил поглинає світло та розсіює різні кольори за напрямками. Синя складова розсіяного світла більше зосереджена поблизу напряму Сонця, ніж жовта й червона. Довший шлях біля горизонту робить цей ефект виразнішим. Колір залежить і від кількості та властивостей пилу: він не однаковий у всі дні.<p><a href="https://science.nasa.gov/solar-system/planets/mars/what-does-a-sunrise-sunset-look-like-on-mars/" target="_blank" rel="noopener">NASA: кольори марсіанського неба та заходу ↗</a></p>'],['Чому вибрати CO₂ недостатньо','У режимі газу вибір CO₂ змінює лише умовну величину молекулярного розсіювання. Він не додає марсіанського пилу, тиску, висотного профілю чи радіуса Марса. Параметр аерозольного послаблення тільки прибирає світло з променя — не додає розсіяного пилом світла до неба. Тому газова модель не може відтворити блакитний захід Марса. Окрема вкладка Марса є пояснювальною схемою за спостереженнями, а не результатом цієї газової формули.'],['Що потрібно для розрахунку пилового неба','Для кожної довжини хвилі λ треба знати, яка частина світла розсіюється, яка поглинається і куди спрямовується розсіяне світло. Кутовий розподіл задає фазова функція P(Θ, λ); Θ — кут розсіювання. На відміну від газової моделі, вона залежить від властивостей пилу та довжини хвилі. Для розсіювання й поглинання без власного випромінювання середовища рівняння переносу має вигляд:<div class="formula">dI<sub>λ</sub>/ds = −β<sub>ext,λ</sub>I<sub>λ</sub> + β<sub>sca,λ</sub>∫ P(Θ,λ)I<sub>λ</sub>(Ω′) dΩ′</div>I<sub>λ</sub> — світло вздовж заданого напряму; s — шлях; β<sub>ext,λ</sub> — коефіцієнт сумарного послаблення; β<sub>sca,λ</sub> — коефіцієнт розсіювання; Ω′ — напрям світла, що може розсіятися в наш промінь. P нормована так, щоб її інтеграл за всіма напрямками дорівнював 1. Перший доданок прибирає світло, другий додає його з інших напрямків. Для Марса потрібні реальні оптичні властивості, розміри й форма пилових частинок, профіль атмосфери та багаторазове розсіювання. Ця версія враховує пил у наближенні одноразового розсіювання; повний багаторазовий перенос не реалізований.']);sky.fields.find(f=>f.key==='pressure').unit='';sky.theory=sky.theory.map(([t,b])=>[t,b.replace('При P = 0 розсіювати світло нічому, тому небо чорне.','При P = 0 релеївського розсіювання немає, тому в цій моделі небо чорне навіть за ненульового аерозольного послаблення: розсіяне аерозолями світло тут не обчислюється.')]);sky.note+=' Газова колонка безрозмірна: це множник оптичної товщини, а не виміряний тиск в атмосферах. Напрями зорі й погляду лежать в одній вертикальній площині з одного боку зеніту; азимут не змінюється.';

 sky.fields=[select('mode','Модель',[['simulation','Спектральна симуляція']],'simulation'),select('planet','Планета та початкові умови',[['earth','Атмосфера Землі'],['mars','Атмосфера Марса'],['custom','Власна атмосфера екзопланети']],'earth'),range('T','Температура зорі',3000,12000,100,5800,'К'),range('sun','Висота зорі',0,90,.5,30,'°'),range('view','Висота точки неба для спектра',0,90,1,20,'°'),range('azimuth','Азимут погляду від зорі',-180,180,1,0,'°'),range('logP','log₁₀ тиску в Па',1,5.3,.05,5.0057),range('airT','Температура атмосфери',150,350,1,288,'К'),range('oxygen','Частка O₂',0,100,1,21,'%'),range('co2','Частка CO₂',0,100,1,0,'%'),range('hydrogen','Частка H₂',0,100,1,0,'%'),range('dust','Кількість аерозолів: оптична товщина при 550 нм',0,1,.01,.05),select('radius','Ефективний радіус пилу',[['0.5','0,5 мкм'],['1.6','1,6 мкм'],['3','3 мкм']],'1.6'),range('dustH','Масштаб висоти аерозолів',.5,20,.1,1.2,'км'),range('alt','Висота спостерігача',0,20,1,0,'км'),range('exposure','Яскравість відображення (log₁₀)',0,4,.1,2.5)];
 sky.fields.push(range('dayPhase','Положення на денній дузі: 0° схід · 90° полудень · 180° захід',0,180,1,60,'°'),range('latitude','Північна широта спостерігача',10,75,1,45,'°'));
 sky.fields.push(range('planetRadius','Радіус власної планети',2500,15000,100,6400,'км'),range('gravity','Прискорення вільного падіння g',2,30,.01,9.8,'м/с²'));
 sky.fields.push(select('aerosol','Властивості аерозолів',[['haze','Параметрична димка'],['mineral','Мінеральний пил: Мі вперед + згладжені бокові напрямки']],'haze'),range('angstrom','Залежність від кольору: показник α',0,4,.1,1.3),range('asymmetry','Розсіювання вперед: параметр g',0,.95,.01,.7),range('albedo','Частка розсіювання без поглинання ω',0,1,.01,.95),select('skyView','Вид сцени',[['panorama','Панорама: схід — південь — захід'],['sun','Ділянка біля зорі: збільшення']],'panorama'));
 sky.fields.push(select('skyPlot','Що показати на графіку',[['radiance','Спектр неба: без нормування'],['tau','Оптична товщина газу'],['shape','Форми спектрів: нормовані окремо']],'radiance'));
 sky.fields.sort((a,b)=>{const rank=k=>({mode:0,planet:1,dayPhase:2,latitude:3}[k]??4);return rank(a.key)-rank(b.key)});
 sky.sub='Спектральна симуляція газу й пилу · наближення одноразового розсіювання';sky.preset={dayPhase:3,latitude:45,mode:'simulation',planet:'mars',T:5800,sun:2,view:3,azimuth:0,logP:Math.log10(600),airT:210,oxygen:0,co2:95,hydrogen:0,dust:.2,radius:1.6,dustH:10,alt:0,exposure:2.5,aerosol:'mineral',skyView:'sun'};
 sky.note='На заході напрям біля зорі та протилежний напрям мають різну яскравість; небо не стає чорним одразу, щойно зоря торкнулася горизонту. Для деталей обери збільшений вид над сценою. Панорама обчислюється зі спектрів, без ручного підфарбовування. До всього неба застосовано спільну екранну криву яскравості зі збереженням співвідношень лінійних RGB-каналів. Цей показ не є точною моделлю камери чи адаптації людського ока. Зміна яскравості відображення не змінює фізичних спектрів. Торкнися панорами, щоб вибрати напрям для спектра; його позначено колом. Розмір диска зорі умовний. Одноразове розсіювання: при густому пилу та поблизу горизонту потрібна перевірка багаторазового внеску; точність кольору реального Марса не гарантована.';
 sky.observe='Зміни положення на денній дузі або натисни «Схід / захід». Порівняй напрям поблизу зорі та вбік. Змінюй газ і пил незалежно. Земля й Марс задають початковий склад газів, але пил і димку можна змінювати в кожному режимі. Обери власну атмосферу, щоб змінювати ще й газову суміш. N₂ заповнює решту суміші до 100%; збільшення однієї частки за потреби зменшує інші. На шкалі тиску 3 означає 10³ = 1000 Па, 5 — 100000 Па. Експозиція змінює лише показ зображення. Для порівняння H₂ та CO₂ спершу встанови кількість аерозолів = 0; залиш тиск, прискорення вільного падіння й зорю незмінними. Стеж за оптичною товщиною газу та його масштабом висоти під сценою. Графік без нормування показує різницю сигналу; схожий блакитний відтінок сам по собі не означає однакового розрахунку.';
 sky.task='Порівняй Землю та Марс при висотах 30° і 2°. Вимкни пил, залишивши CO₂: чи збережеться сяйво біля зорі? Зміни радіус частинок. Порівнюй небо зі спільною експозицією. Запиши спектральний сигнал у напрямках 0° та 60° від зорі.';
 sky.limit='Чисельна сферична модель одноразового розсіювання в експоненційній атмосфері. Молекулярне поглинання, хмари, багаторазове розсіювання та відбиття поверхні не включені. Модель димки — параметрична функція HG; її початкові значення не є вимірюванням конкретного дня. Мінеральний пил — сферична суміш n=1,5 із 3% гематиту Querry (звичайна вісь), ефективна дисперсія 0,2; це навчальна мікрофізична модель, не точне відтворення конкретного марсіанського спостереження.';
 sky.theory=sky.theory.filter(([t])=>!['Чому вибрати CO₂ недостатньо','Які параметри атмосфери рахує модель','Як складається світло всього неба','Що означає колір на екрані'].includes(t));
 sky.theory=sky.theory.filter(([t])=>!['Оптична товщина','Як рахується колір неба','Розсіювання, а не нове світло'].includes(t));
 sky.theory.push(['Власна атмосфера далекої планети','У третьому режимі можна незалежно досліджувати тиск, температуру газу, суміш N₂/O₂/CO₂/H₂, радіус планети, прискорення вільного падіння й модель пилу. Усі частки додаються до 100%: N₂ — залишок. Кнопка випадкового набору створює тестові параметри, а не відкриту або гарантовано стійку реальну планету. Схожа залежність молекулярного розсіювання від довжини хвилі означає, що заміна одного прозорого газу іншим не зобов’язана різко змінювати відтінок неба. Вплив може проявлятися у яскравості, оптичній товщині та масштабі висоти. Газове поглинання, фотохімія, конденсація й кліматична рівновага тут не розраховуються, тому це дослідницька навчальна модель у вказаних межах.'],['Чому зоря рухається дугою','Небесні світила змінюють і висоту, і напрям над горизонтом через обертання планети. Тут показано денний шлях зорі в день рівнодення: схід ліворуч, полудень у напрямку півдня, захід праворуч. Широта визначає висоту дуги. Кут H відраховується від полудня, а φ — широта:<div class="formula">sin h = cos φ cos H<br>A = atan2(sin H, sin φ cos H)</div>h — висота, A — азимут від півдня (від’ємний на сході), H змінюється від −90° до +90°. На широті 45° зоря в полудень піднімається до 45°. Це прискорена демонстрація обертання, не календарний прогноз. На Марсі також прийнято умовний день рівнодення. Напрям погляду для спектра задається відносно поточного напряму зорі.'],['Як рахується ця симуляція','Зоря дає тепловий спектр; його інтеграл у 380–780 нм нормовано до одиниці, тому температура змінює форму спектра за сталої вхідної видимої енергії. Густини газу та пилу спадають із висотою. Газова суміш визначає середню масу молекули й масштаб висоти:<div class="formula">N(z)=N₀ exp(−z/H)<br>H=k<sub>B</sub>T/(m̄g)<br>β<sub>R</sub>(λ,z)=Σᵢ Nᵢ(z)σᵢ(λ)</div>Перерізи газів отримано з рефрактивності й деполяризації за <a href="https://pds-atmospheres.nmsu.edu/education_and_outreach/encyclopedia/rayleigh_optical.htm" target="_blank" rel="noopener">таблицею NASA PDS (Allen)</a>; N₂, O₂, CO₂, H₂. Вибір Марса встановлює радіус 3389,5 км, g=3,71 м/с², тиск 600 Па, температуру 210 К та початкову суміш 95% CO₂ + 5% N₂. Аргон у цій скороченій суміші не включений. Земля: 6371 км, 9,81 м/с², 101325 Па, 288 К, 79% N₂ + 21% O₂. Це початкові наближення, не повні атмосферні профілі.'],['Що змінює мінеральний пил у моделі Мі','У цьому підрозділі йдеться саме про мінеральний набір, а не параметричну димку. Оптичну товщину задаємо при 550 нм. Для інших довжин хвиль вона випливає з розрахованого перерізу послаблення. Світло в напрямку ока додається через диференціальний переріз розсіювання. Він залежить від кута та довжини хвилі; перерізи послаблення й розсіювання обчислено за розв’язком Мі. Поблизу напрямку Сонця (0–20°) залишено спектральний розподіл Мі. На 20–60° його плавно з’єднано зі згладженим боковим і зворотним розсіюванням HG; повний розподіл після цього нормовано до одиниці. Межі з’єднання — прийняте навчальне наближення, не виміряні параметри марсіанського пилу. Один лише HG не зберігав потрібної спектральної структури переднього розсіювання. Це прибирає надмірний пік зворотного розсіювання ідеальних сфер; цей пік створював хибну яскраву пляму навпроти зорі. Така заміна є навчальним наближенням, а не виміряною фазовою функцією марсіанського пилу. Радіуси — три окремі розраховані набори, не довільна інтерполяція. Для розрахунку перерізів пил має модифікований гамма-розподіл розмірів із ефективною дисперсією 0,2. Суміш гематиту й основи отримано правилом Максвелла — Гарнетта. <a href="https://doi.org/10.1364/AO.53.001808" target="_blank" rel="noopener">Ehlers et al. (2014)</a>; <a href="https://refractiveindex.info/?shelf=main&book=Fe2O3&page=Querry-o" target="_blank" rel="noopener">оптичні дані Querry</a>.'],['Від інтеграла до кольору','У кожній точці променя враховано послаблення від зорі до частинки та від частинки до ока:<div class="formula">I<sub>неба,λ</sub>=∫ F<sub>λ</sub> exp[−τ<sub>in</sub>−τ<sub>out</sub>] [β<sub>R</sub>P<sub>R</sub>+β<sub>dust,sca</sub>P<sub>dust</sub>] ds</div>Планета закриває світло для точок у її тіні. Усі довжини хвиль проходять цю процедуру, потім спектр зважується функціями CIE й переводиться в лінійні канали RGB. До всього неба застосовано одну логарифмічну екранну криву зі сталою опорною яскравістю 10 у модельних одиницях. Максимальний лінійний RGB-канал задає яскравість точки L; усі три канали множаться на один коефіцієнт:<div class="formula">D = min[1, ln(1 + eL) / ln(1 + 10e)]<br>RGB<sub>екран,лін</sub> = RGB<sub>лін</sub> D/L</div>e — налаштування яскравості відображення. Потім виконується кодування sRGB. Так зберігаються співвідношення додатних лінійних каналів; повного прогнозу сприйняття людським зором тут немає. Кожна панорама використовує ту саму опорну яскравість, без власного нормування за її найяскравішою точкою. Це спосіб показати великий діапазон яскравостей на екрані, не новий закон розсіювання. Графік «Спектр неба: без нормування» показує обчислений сигнал у смузі 10 нм, віднесений до вхідного видимого потоку та тілесного кута. Експозиція картинки на графік не впливає. Режим «Оптична товщина газу» показує вертикальну газову товщину за кожної довжини хвилі від поверхні планети. Лише режим «Форми спектрів» нормує небо й пряме світло окремо за максимумом: він допомагає порівняти форму, але приховує різницю яскравості. Це чисельне наближення одноразового розсіювання; повторні розсіювання, важливі в оптично товстому пилу, не додані.']);
 sky.theory.push(['Чи може водневе небо бути блакитним?','Так. У цій моделі водень — молекули H₂, а не окремі атоми. Електричне поле світла трохи зміщує заряди всередині молекули, і вона розсіює світло. Короткі хвилі розсіюються сильніше: це релеївське розсіювання, і воно відбувається не лише на кисні та азоті. Для H₂ використано формулу Dalgarno–Williams із <a href="https://pds-atmospheres.nmsu.edu/education_and_outreach/encyclopedia/rayleigh_optical.htm" target="_blank" rel="noopener">NASA PDS</a>. При 450 нм переріз приблизно у 4,5 раза більший, ніж при 650 нм. За однакового тиску та тяжіння легких молекул у стовпі більше:<div class="formula">N<sub>стовпа</sub> = p/(m̄g)<br>τ<sub>R</sub>(λ) = N<sub>стовпа</sub> σ<sub>R</sub>(λ)</div>Тому не слід порівнювати гази тільки за перерізом однієї молекули. Спробуй 100% H₂, аерозолі = 0 і зорю 5800 К: блакитний відтінок можливий. Після цього окремо додай пил. Колір також залежить від спектра зорі, поглинальних домішок і хмар; вони не всі враховані тут. Блакитне небо саме по собі не є ознакою кисню або життя.'],['Пил і аерозолі: що можна змінювати','Маленькі тверді частинки й краплі, що висять у газі, називають аерозолями. Пил — один із їхніх різновидів. Вони доступні для Землі, Марса й власної планети; вибір планети лише відновлює початкові значення. Кількість задає оптична товщина: більше значення означає сильніше послаблення й більше можливостей для розсіювання. Масштаб висоти визначає, як швидко кількість частинок спадає з висотою. У мінеральній моделі обирай один із розрахованих ефективних радіусів. У моделі димки властивості задаються окремо: α визначає залежність від кольору, g — перевагу розсіювання вперед, ω — частку послабленого світла, що розсіюється, а не поглинається.<div class="formula">τ<sub>a</sub>(λ)=τ<sub>a,550</sub>(550 нм/λ)<sup>α</sup><br>P<sub>HG</sub>(Θ)=(1−g²)/[4π(1+g²−2g cos Θ)<sup>3/2</sup>]<br>β<sub>sca</sub>=ωβ<sub>ext</sub></div>Це нормована <a href="https://pages.nist.gov/SCATMECH/docs/phase.htm" target="_blank" rel="noopener">фазова функція Генні — Грінстейна (NIST)</a>. Вона описує загальну спрямованість, але не відтворює тонкі кольорові особливості конкретного пилу чи веселку. Для Землі початково обрано параметричну димку, для Марса — мінеральний пил. Це два навчальні наближення, а не універсальні властивості всіх земних і марсіанських частинок. Для бокової та зворотної частини мінерального набору використано HG із g, оціненим із таблиці Мі; переднє розсіювання зберігає детальну залежність від кольору. Після з’єднання нормування зберігає енергію розсіяного світла, але не гарантує точного середнього кута реального пилу. <a href="https://academic.oup.com/mnras/article/537/2/1489/7965978" target="_blank" rel="noopener">Дослідження впливу форми марсіанського пилу на розсіювання</a>.'],['Чому нинішня картинка не є прогнозом реального заходу','Поблизу горизонту світло проходить довгий шлях. Частина променів розсіюється кілька разів, до неба додається світло від поверхні, а атмосферне заломлення змінює видиме положення Сонця. Ці внески тут ще не обчислені. Отже, особливо біля горизонту, абсолютна яскравість, ширина сяйва й відтінки можуть відрізнятися від спостережень. На Марсі біля Сонця спостерігають блакитне сяйво на теплішому тлі; його не треба шукати по всьому небу. Збільшений вид показує ту саму обчислену ділянку, без домальовування кольору. Земний захід також не має одного постійного вигляду: пил, вологість, хмари й напрям погляду змінюють картину. <a href="https://science.nasa.gov/resource/sunset-at-mars-gale-crater-curiosity/" target="_blank" rel="noopener">Порівняння зі спостереженнями Curiosity</a>.']);
 mol.fields.find(f=>f.key==='J').label='Верхнє обертальне число J';mol.note=mol.note.replace('Кожен цикл умовно повторює підготовку збудженої молекули.','Один запуск показує один підготовлений процес; для повторення потрібен новий запуск.');mol.theory=mol.theory.map(([t,b])=>[t,b.replace('з основного v = 0, J = 0 до стану з вибраними v та J','зі стану v = 0, J−1 до електронно-збудженого стану з вибраними v та J (гілка ΔJ = +1)').replace('E<sub>ел</sub> + ℏωv + BJ(J + 1)<br>λ','E<sub>ел</sub> + ℏωv + 2BJ<br>λ')]);mol.theory.push(['Як читати поглинання й випромінювання','В обертальному та коливально-обертальному режимах молекула спочатку збуджена й віддає один фотон: енергія поглинання цього запуску дорівнює нулю. В електронно-коливальному режимі вона поглинає фотон, переходячи з J−1 на J: енергія випромінювання дорівнює нулю. Для двох електронних станів умовно взято однакові B та коливальний крок. Їхні нульові коливальні енергії скорочуються в різниці. Набір електронно-коливальних ліній показує переходи з різних початкових J−1, а не з одного J = 0 у будь-який J. Вибрано гілку зі зміною J на одиницю; ймовірності, населеності й правила для конкретної реальної молекули ця умовна модель не розраховує. Піки на графіку позначають положення ліній та умовні сили, а не спектр світла після проходження газу. У флуоресценції показано поглинання, передачу енергії оточенню й окремий випромінений фотон.']);
 atom.theory.push(['Яку точність має формула Гідрогену','Протон теж має скінченну масу й бере участь у відносному русі. Щоб урахувати це в нерелятивістській моделі, масу електрона замінюють зведеною масою μ:<div class="formula">μ = m<sub>e</sub>m<sub>p</sub>/(m<sub>e</sub> + m<sub>p</sub>)<br>E<sub>n</sub> = −13,5983 еВ / n²</div>m<sub>e</sub> — маса електрона, m<sub>p</sub> — протона. У коді коефіцієнт обчислюється зі сталої Рідберґа та відношення мас CODATA; у формулі його округлено. Для 3 → 2 маємо близько 656,47 нм у вакуумі. Значення близько 656,3 нм зазвичай наводять у повітрі. Тонка структура, лембівський зсув і спектральне розширення тут не розраховуються.']);

 const inter=exps.find(e=>e.id==='interference');inter.fields.find(f=>f.key==='mode').value='photons';inter.fields.find(f=>f.key==='rate').value=10;inter.fields.push(select('prediction','Теоретичний прогноз на екрані',[['0','Прихований: лише накопичені події'],['1','Показати прогноз для порівняння']],'0'));inter.note='Вгорі — умовна схема установки; нижче той самий екран розгорнуто до нас. Горизонтальна координата x має сталу шкалу −15…+15 мм. Одна точка означає одну реєстрацію. Висота точки обирається рівномірно для наочності довгих щілин; це не окремий розрахунок вертикальної дифракції. Біле кільце виділяє останнє попадання. Під екраном кожен стовпчик рахує події в смужці завширшки 0,5 мм. Частота задає реєстрації в цьому полі екрана, не повний потік джерела. Шляхи окремих фотонів не моделюються. Зміна фізичних параметрів, частоти або режиму починає нове накопичення; перемикач прогнозу зберігає точки.';inter.observe='Почни з порожнього екрана. Натисни «+1 попадання» кілька разів: кожен раз з’являється одна випадкова точка. Додай 100, потім 1000: у деяких вертикальних смугах точок стає більше, а проміжки залишаються рідкими. Стовпчики внизу показують цей розподіл чисельно. Лише потім увімкни теоретичний прогноз. Порівняй когерентні шляхи з повною втратою когерентності. У другому випадку дрібні смуги зникають, але широка огинаюча залишається.';inter.theory.unshift(['Як читати цю візуалізацію','Перша частина — схема: джерело освітлює дві щілини, а за ними стоїть екран-детектор. Вона пояснює будову установки, а не шлях окремого фотона. Друга частина — збільшений екран спереду. Спочатку він порожній. Кожна нова точка означає локальну подію реєстрації; попередні точки зберігаються. Окрема подія випадкова, тому кілька точок ще не утворюють зрозумілої смуги. Після сотень і тисяч подій стають помітні вертикальні ділянки з більшою та меншою кількістю точок. Третя частина підраховує події в сусідніх вертикальних смужках. Висота кожного стовпчика — кількість зареєстрованих подій у відповідній ділянці, не висота хвилі. Стовпчики усереднюють події по 0,5 мм: якщо обрати дуже вузькі смуги, такий підрахунок може їх згладжувати.']);inter.theory.push(['Чому випадкові точки дають закономірні смуги','Модель не вирішує наперед, куди має прилетіти наступний фотон. Вона випадково обирає його координату з розподілу ймовірності, пропорційного розрахованій інтенсивності. Нормування виконується на видимому полі −15…+15 мм:<div class="formula">p(x) = I(x) / ∫<sub>поле</sub> I(x′) dx′<br>P<sub>смужки</sub> = ∫<sub>смужка</sub> p(x) dx<br>⟨N<sub>смужки</sub>⟩ = N P<sub>смужки</sub></div>p(x) — густина ймовірності; N — загальна кількість подій. Кутові дужки позначають очікуване середнє за багато повторень. Реальна кількість у кожному стовпчику випадково відхиляється від цього середнього. При малому N відхилення великі відносно числа подій; зі зростанням N відносний шум зменшується. Готові світлі смуги не підмальовуються в режимі попадань: вони виникають із самих точок. Перемикач прогнозу додає окремий теоретичний шар для порівняння, не змінюючи згенерованих подій.']);inter.theory.push(['Що означає зникнення інтерференції','Без визначення шляху та за збереженої когерентності додаються амплітуди двох можливих внесків:<div class="formula">p(x) ∝ |ψ₁(x) + ψ₂(x)|²</div>Виникає інтерференційний внесок: у деяких місцях імовірність підсилюється, в інших зменшується. Якщо узгодженість повністю втрачена або отримано розрізнювану інформацію про шлях, в усередненій картині додаються ймовірності:<div class="formula">p(x) ∝ |ψ₁(x)|² + |ψ₂(x)|²</div>У симетричній далекопольовій моделі зникають дрібні смуги, але лишається дифракційна огинаюча. Результат не потребує одночасної присутності багатьох фотонів у приладі: накопичення можливе й за поодинокої подачі. Повзунок частоти тут керує лише темпом демонстраційних реєстрацій; він не моделює просторову густину фотонів усередині установки.']);inter.task='Додай по черзі 1, 10, 100 і 1000 подій. Порівняй точки, стовпчики й теоретичний прогноз. Повтори з нуля: точні місця відрізнятимуться, але загальний профіль буде подібним. Потім зафіксуй a, d, L і порівняй λ = 400, 550, 700 нм. Для втрати когерентності перевір зникнення дрібних смуг.';

 pol.fields.push(select('waterBeam','Яке світло показати у 3D',[['glare','Відблиск від поверхні'],['detail','Світло від підводної деталі']],'glare'));
 pol.fields.push(select('waterExposure','Як порівнювати картинки води',[['shared','Однакова умовна експозиція'],['contrast','Окреме нормування: порівняти контраст']],'shared'));pol.note+=' У водному режимі 3D показує вибраний потік: відблиск або світло від підводної деталі. В обох випадках промінь уже йде від води до фільтра; проходження межі води тут не зображене. Для води обидва поля збільшено одним множником: масштаб задано світлом перед фільтрами й лишається однаковим уздовж усього променя. Після фільтра поле не збільшується окремо. При повному гасінні кольорових кривих після фільтра немає; лишається лише напрямна вісь. cB у легенді — магнітне поле, помножене на c, щоб порівнювати геометрію векторів з E.';pol.theory.push(['Що видно, коли відблиск зникає?','До ока надходять два різні потоки: світло, відбите поверхнею води (відблиск), і світло від предметів під водою. Поляризатор діє на обидва, але по-різному, якщо вони мають різну поляризацію. Біля кута Брюстера відблиск майже повністю s-поляризований. Фільтр з віссю p майже прибирає його. Світло від риби в нашій спрощеній моделі неполяризоване: один ідеальний фільтр пропускає половину цього потоку. Отже, зникає переважно відблиск, а риба тьмяніє, проте залишається видимою. Перемикач над схемою дозволяє побачити кожен потік окремо.<div class="formula">I<sub>око</sub> = I<sub>відблиск</sub> + I<sub>деталь</sub><br>I<sub>деталь, після 1 фільтра</sub> = ½ I<sub>деталь, до</sub></div>Це не означає, що таке положення фільтра завжди найкраще: важливі і контраст, і кількість світла. Два ідеальні схрещені фільтри гасять обидві складові: тоді права картинка чорна навіть у режимі окремого нормування. Для справжньої підводної сцени поляризація світла складніша; тут світло від деталі задано умовно, а не розраховано після проходження води.']);pol.theory.push(['Два різні відсотки у водному режимі','За одиницю беремо світло, яке падає на воду. Частина відбивається: R = (R<sub>s</sub> + R<sub>p</sub>)/2. Саме цей відблиск, а не весь початковий потік, надходить на перший поляризатор. Тому частка від початкового освітлення й частка від відблиску мають різні знаменники:<div class="formula">R = I<sub>до</sub> / I<sub>осв</sub><br>T<sub>фільтрів</sub> = I<sub>після</sub> / I<sub>до</sub><br>I<sub>після</sub> / I<sub>осв</sub> = R T<sub>фільтрів</sub></div>Щоб перевести частку у відсотки, помнож її на 100. Наприклад, R ≈ 0,0433 означає 4,33% освітлення у відблиску. Якщо після фільтра лишається 0,000123 освітлення, це 0,0123% освітлення, або приблизно 0,284% від початкового відблиску. Це той самий результат з двома різними базами порівняння. Числа на 3D схемі й у таблиці тепер прямо називають, до чого віднесений відсоток.']);pol.theory.push(['Чому хвиля після фільтра може майже зникнути','За кута Брюстера ідеальний відблиск від гладкої води має тільки s-складову. Поляризатор з віссю p (0° у нашій системі) її не пропускає. Біля цього кута, але не точно на ньому, залишається мала p-складова: після фільтра поле слабке, але не обов’язково нульове. Відношення середніх інтенсивностей пов’язане з квадратом відповідного ефективного поля: при пропусканні 0,25% характерний масштаб поля становить приблизно 5% початкового. Це пояснює майже пряму криву на спільній шкалі. Для складної або частково поляризованої хвилі йдеться про усереднене за часом поле в квадраті; окремий кадр анімації не визначає інтенсивність. Картинки з рибою поєднують обидві складові. 3D схема показує лише вибрану складову; зникнення відблиску на ній не означає зникнення світла від риби.']);

 // Current transport configuration and explanation replace superseded first-order notes.
 sky.fields.find(f=>f.key==='radius').options=[['1.4','1,4 мкм · еталон Марса (Schneegans 2024)'],['0.5','0,5 мкм · гамма-модель'],['1.6','1,6 мкм · гамма-модель'],['3','3 мкм · гамма-модель']];
 sky.fields.find(f=>f.key==='aerosol').options=[['haze','Параметрична димка'],['mineral','Мінеральний пил: спектральні таблиці Мі']];
 sky.fields.push(range('ozone','Озоновий стовп',0,600,10,300,'DU'),range('ground','Частка світла, відбита поверхнею',0,.8,.05,.15),select('displayMode','Відображення яскравості',[['auto','Спільна адаптація до всього неба'],['fixed','Стала експозиція: порівняння атмосфер']],'auto'));
 sky.sub='Газ, пил і світло, що розсіюється кілька разів';
 sky.preset={...sky.preset,radius:1.4,ozone:0,ground:.15,displayMode:'auto'};
 sky.note='Спектральний сферичний перенос: пряме, одноразово й багаторазово розсіяне світло, поглинання озоном та відбиття від поверхні. Кольори обчислено зі спектрів. Яскравість екрана має окреме налаштування; для порівняння різних атмосфер обери сталу експозицію. Біле коло позначає напрям для графіка. Розмір зорі умовний. Обчислення займає кілька–кількадесят секунд; під час нього попередня картинка прихована. Це навчальна модель, а не прогноз конкретного дня.';
 sky.observe='Почни із Землі та Марса при однаковій температурі зорі. Порівняй полудень і положення біля горизонту. Для Марса залиш еталонний пил 1,4 мкм, потім зміни його кількість. Блакитне сяйво очікується біля Сонця на теплішому тлі, а не по всьому небу. Димку, пил, озон і відбиття поверхні можна змінювати незалежно. Власна планета відкриває склад газу, тиск і прискорення вільного падіння. Для порівняння яскравостей обери сталу експозицію: автоматична адаптація може приховувати різницю загального сигналу. Дочекайся завершення розрахунку.';
 sky.limit='Скалярний стаціонарний перенос у сферично симетричній атмосфері. Немає хмар, атмосферного заломлення, поляризації й газового поглинання, крім озону. Пилові частинки наближено сферами; кутова та спектральна сітки скінченні. Число траєкторій обмежене; статистична похибка спектра наведена в обчисленнях, але не оцінює всіх похибок моделі.';
 sky.theory=[
 ['Чому небо взагалі світиться','Світло зорі може пройти до ока прямо, змінити напрям на молекулі чи частинці пилу або поглинутися. Зміну напряму називають розсіюванням. Коли дивимося вбік від зорі, бачимо світло, спрямоване до нас атмосферою. Прозорі молекули сильніше розсіюють короткі хвилі: у чистій земній атмосфері це сприяє блакитному кольору. Але весь колір визначають також спектр зорі, пил і поглинання, а не лише назва газу.'],
 ['Чому Марс має інші кольори','Тонка атмосфера Марса містить завислий мінеральний пил. Він розсіює світло інакше, ніж окремі молекули. Денне небо часто має приглушений рудуватий, жовтий або коричнюватий відтінок. Біля низького Сонця блакитна складова може бути помітнішою саме поблизу його напряму. Це не окремий синій диск і не однаковий колір усього неба. Кількість і розміри пилу впливають на результат. <p><a href="https://science.nasa.gov/solar-system/planets/mars/what-does-a-sunrise-sunset-look-like-on-mars/" target="_blank" rel="noopener">NASA: спостереження та пояснення кольорів ↗</a> · <a href="https://science.nasa.gov/resource/sunset-at-mars-gale-crater-curiosity/" target="_blank" rel="noopener">Калібрований захід Curiosity ↗</a></p>'],
 ['Звідки взято властивості пилу','Еталон Марса 1,4 мкм використовує опубліковані спектральні таблиці realistic Mars із CosmoScout VR: розсіювання, поглинання, розподіл напрямів і висотний профіль. Це модель суміші розмірів сферичних частинок, а не всі частинки одного радіуса. Дані пов’язані з роботою Schneegans, Meyran, Ginkel, Zachmann і Gerndt (2024). У нашому розрахунку використано їхні оптичні дані, але інший чисельний розв’язувач переносу. Оптична товщина при 550 нм масштабує кількість пилу, а масштаб висоти розтягує профіль зі збереженням заданої товщини. Інші радіуси — окремі навчальні гамма-розподіли з ефективною дисперсією 0,2, n≈1,5 та домішкою гематиту. Для власної планети еталонний пункт 1,4 мкм також означає цей набір оптичних властивостей, а не виміряне іншопланетне середовище.<p><a href="https://doi.org/10.1111/cgf.15010" target="_blank" rel="noopener">Стаття й метод Мі ↗</a> · <a href="https://github.com/cosmoscout/cosmoscout-vr/tree/main/plugins/csp-atmospheres/scattering-table-generator/output" target="_blank" rel="noopener">Вихідні таблиці CosmoScout VR / DLR ↗</a> · <a href="https://doi.org/10.1364/AO.53.001808" target="_blank" rel="noopener">Ehlers et al.: гамма-модель частинок ↗</a></p>'],
 ['Чому одного розсіювання недостатньо','Світло може змінити напрям кілька разів, перш ніж потрапить до ока. Наприклад, спершу розсіятися біля зорі, потім на іншій частинці й лише після цього дійти до спостерігача. Таке багаторазове розсіювання додає розсіяне освітлення до тла. Воно особливо важливе, коли шлях крізь атмосферу довгий. Рівняння враховує втрати та надходження з усіх напрямів:<div class="formula">dI<sub>λ</sub>/ds = −β<sub>ext,λ</sub>I<sub>λ</sub> + β<sub>sca,λ</sub>∫ P<sub>λ</sub>(Ω,Ω′)I<sub>λ</sub>(Ω′) dΩ′</div>I — спектральна яскравість у заданому напрямку, s — пройдений шлях. β<sub>ext</sub> задає сумарне послаблення, β<sub>sca</sub> — розсіювання; їхня різниця описує поглинання. P задає, як світло розподіляється за напрямами; інтеграл P за тілесним кутом дорівнює 1. Тілесний кут — міра ділянки напрямів у просторі, одиниця — стерадіан (ср). Поверхня відбиває задану частку світла рівномірно за законом Ламберта. Відбите світло також може знову розсіятися в атмосфері.'],
 ['Як це обчислюється тут','Одноразове розсіювання інтегрується вздовж променя у сферичній атмосфері. Для повторних подій запускаємо випадкові зворотні траєкторії від ока — метод Монте-Карло. На кожному зіткненні оцінюємо світло від зорі з урахуванням тіні планети й поглинання. Всі довжини хвиль мають спільну геометрію траєкторії, але окремі ваги ймовірності для реальних та нульових зіткнень. Напрями вибираються із суміші розподілів навколо попереднього напряму та зорі, з компенсацією ваг. Це зменшує шум без домальовування кольорів. Для картинки повторний внесок обчислюється на грубшій кутовій сітці й інтерполюється, а прямий однократний внесок має густішу сітку біля зорі. Для вибраного спектра використано 4096 спільних траєкторій для всіх довжин хвиль; консервативна оцінка похибки 1σ (сума стандартних похибок спектральних внесків) наведена під графіком в обчисленнях. Після десяти зіткнень частину траєкторій випадково завершуємо з компенсацією ваги; граничний порядок — 64. Для картинки шумний повторний внесок додатково усереднюється з сусідніми напрямами, якщо різниця лежить у межах статистичної похибки. Усі кольори мають однакові ваги усереднення. Графік вибраного спектра не згладжується. Картинка може мати похибки інтерполяції, згладжування й шум. Це не той самий алгоритм реального часу, що у статті CosmoScout.<p><a href="https://pbr-book.org/4ed/Light_Transport_II_Volume_Rendering" target="_blank" rel="noopener">Pharr, Jakob, Humphreys: об’ємний перенос, Монте-Карло та нульові зіткнення ↗</a></p>'],
 ['Газ, тиск і прискорення вільного падіння','Тиск задає вагу газового стовпа. За однакового тиску легких молекул у ньому більше. Температура й маса молекули також визначають, як швидко густина спадає з висотою:<div class="formula">N<sub>стовпа</sub> = p/(m̄g)<br>H = k<sub>B</sub>T/(m̄g)<br>N(z) = N<sub>0</sub> exp(−z/H)<br>τ<sub>R</sub>(λ) = N<sub>стовпа</sub> Σᵢ fᵢσᵢ(λ)</div>m̄ — середня маса молекули, g — прискорення вільного падіння, fᵢ — частка газу, σᵢ — його переріз розсіювання. Для Землі g=9,81 м/с², для Марса g=3,71 м/с² — зафіксовані. У режимі власної планети g змінюється. Земний набір: 101325 Па, 288 К, 79% N₂ і 21% O₂; марсіанський: 600 Па, 210 К, 95% CO₂ і 5% N₂. Аргон та інші малі домішки не включені. H₂ теж сильніше розсіює короткі хвилі, тому водневе небо може бути блакитним. Заміна газу не зобов’язана змінювати блакитний колір на зовсім інший, але змінює товщину й яскравість. Власні частки нормуються до 100%, N₂ — залишок.<p><a href="https://pds-atmospheres.nmsu.edu/education_and_outreach/encyclopedia/rayleigh_optical.htm" target="_blank" rel="noopener">NASA PDS: перерізи та формула Dalgarno–Williams для H₂ ↗</a></p>'],
 ['Пил, димка й озон','Аерозолі — маленькі частинки й краплі, що висять у газі. У режимі димки залежність від кольору й напрямку задається параметрами:<div class="formula">τ<sub>a</sub>(λ) = τ<sub>a,550</sub>(550 нм/λ)<sup>α</sup><br>P<sub>HG</sub>(Θ) = (1−g²)/[4π(1+g²−2g cos Θ)<sup>3/2</sup>]<br>β<sub>sca</sub> = ωβ<sub>ext</sub></div>Тут g — параметр спрямованості димки, не прискорення вільного падіння. α задає залежність від довжини хвилі, ω — частку послаблення за рахунок розсіювання. Цей простий розподіл не відтворює всіх кольорових особливостей мінерального пилу. Озон поглинає частину видимого світла; його стовп задається в одиницях Добсона (DU). 300 DU — земне початкове значення, не універсальна константа. Профіль і спектр поглинання озону взято з земного набору CosmoScout. Інші газові смуги поглинання в цій версії відсутні.<p><a href="https://pages.nist.gov/SCATMECH/docs/phase.htm" target="_blank" rel="noopener">NIST: фазові функції ↗</a> · <a href="https://github.com/cosmoscout/cosmoscout-vr/tree/main/plugins/csp-atmospheres/scattering-table-generator/output" target="_blank" rel="noopener">Таблиці поглинання озоном ↗</a></p>'],
 ['Спектр і колір картинки — різні речі','Видимий потік зорі у 380–780 нм нормовано до одиниці. Температура змінює його спектр за сталої вхідної видимої енергії. Розрахунок виконується для 15 довжин хвиль. Графік без нормування показує спектральну густину сигналу неба на нанометр і стерадіан; експозиція на нього не впливає. Режим форм нормує спектри незалежно й приховує різницю їхньої загальної яскравості. Для картинки спектр зважується колірними функціями CIE, потім переводиться в RGB. У режимі адаптації один множник для всієї сцени вибирається за середньою логарифмічною яскравістю з екранним орієнтиром 0,35 у лінійній шкалі. Значення експозиції 2,5 — базова поправка в цьому режимі. Для зіставлення різних атмосфер потрібна стала експозиція. Екран стискає великий діапазон яскравостей за спільною для трьох каналів кривою; це не новий закон розсіювання. Немає окремо домальованого синього кола чи другого джерела на протилежному горизонті. Колір залежить і від дисплея, а його точність обмежена оптичними даними та сіткою.'],
 ['Рух зорі та межі моделі','Камера розташована біля поверхні. Денна дуга описує рівнодення: схід → полудень → захід, а не рух зорі в космос. На широті φ висота h й азимут A від півдня пов’язані з годинним кутом H:<div class="formula">sin h = cos φ cos H<br>A = atan2(sin H, sin φ cos H)</div>Положення змінюється лише після готового кадру, тому відтворення не показує застарілі кольори. Це прискорена демонстрація, не календарний прогноз. Модель не включає хмари, атмосферне заломлення, поляризацію, реальну форму пилових частинок та всі газові смуги поглинання. У джерельній моделі сферичні частинки можуть перебільшувати зворотне розсіювання; це межа оптичної моделі, яку не виправляють прихованим підфарбовуванням. Чисельна й спостережна перевірки не гарантують кольору конкретного заходу.']
 ];

 sky.fields.push(select('sunFov','Поле зору збільшеного виду',[['10','10° · найбільше збільшення'],['20','20° · околиця Сонця'],['40','40° · ширший вид']],'20'));
 sky.preset.skyView='panorama';sky.preset.dayPhase=177;sky.preset.sunFov=20;
 sky.note=sky.note.replace('Для деталей обери збільшений вид над сценою.','').replace('Біле коло позначає напрям для графіка.','Біле коло на панорамі позначає напрям для графіка. Поруч окрема камера показує небо навколо Сонця, з тією самою експозицією.');
 sky.theory.unshift(['Де шукати блакитне сяйво?','Блакитне сяйво зосереджене поблизу напряму Сонця. На панорамі 200° кілька градусів займають маленьку частину картинки. Праворуч окрема камера спрямована точно на Сонце: воно залишається в центрі кадру. Кутова ширина видимої ділянки називається полем зору. Тут можна обрати 10°, 20° або 40°: менше значення означає більше збільшення. Це збільшення тієї самої розрахованої сцени, а не домальована блакитна пляма. Обидва види мають спільну експозицію, тому зміна масштабу не змінює колір чи яскравість розрахованого напрямку. На фото блакитна область може мати іншу ширину й насиченість: вони залежать від реального пилу та умов знімання. Модель не підігнана під цей окремий знімок.<figure class="roverReference"><img src="./mars-curiosity-sunset.jpg" loading="lazy" width="1344" height="1080" alt="Калібрований знімок Curiosity: блакитне небо поблизу Сонця над марсіанським горизонтом"><figcaption>Спостереження для порівняння: Curiosity, кратер Ґейл, 15 квітня 2015 року. Фото NASA/JPL-Caltech/MSSS/Texas A&amp;M Univ.; колір калібрований і збалансований. Це фото, не результат симуляції. <a href="https://www.jpl.nasa.gov/images/pia19400-sunset-in-mars-gale-crater/" target="_blank" rel="noopener">Оригінал NASA ↗</a> · <a href="https://thealphacentauri.net/139309-blakitniy-zahid-soncya-na-marsi/" target="_blank" rel="noopener">Надіслана стаття ↗</a></figcaption></figure>']);

}
